"""Wrap assets/data/portrait-lum.bin as a JS file so the portrait also works over file://.

fetch() cannot read local files from a file:// page, but a <script> tag can.
Run again whenever portrait-lum.bin changes:  python tools/lum_js.py
"""
import base64
from pathlib import Path

root = Path(__file__).resolve().parent.parent
src = root / "assets" / "data" / "portrait-lum.bin"
dst = root / "assets" / "data" / "portrait-lum.js"
b64 = base64.b64encode(src.read_bytes()).decode("ascii")
dst.write_text(
    "/* Generated by tools/lum_js.py from portrait-lum.bin. Do not edit. */\n"
    f'window.PORTRAIT_LUM = "{b64}";\n',
    encoding="utf-8",
)
print(f"wrote {dst.relative_to(root)} ({dst.stat().st_size} bytes)")
